        val sr = InputReader(BufferedReader(InputStreamReader(System.`in`)))
        val sw = PrintWriter(System.out)
        val task = Task(sr, sw)
        task.solve()
        sw.flush()
    }
}

class Task(private val sr: InputReader, private val sw: PrintWriter) : Closeable {
    fun solve() {
        val n = sr.nextInt()
        val str = sr.nextString()
        var max = 0
        var i = 0
        while (i < str.length) {
            if (str[i].isLowerCase()) {
                val set = HashSet<Char>()
                var j = i
                while (j < str.length) {
                    if (str[j].isLowerCase()) {
                        set.add(str[j])
                    } else {
                        break
                    }
                    j++
                }
                max = maxOf(set.size, max)
            }
            i++
        }
        sw.println(max)
    }

    override fun close() {
        sr.close()
        sw.close()
    }
}

class InputReader(private val reader: BufferedReader) : Closeable {
    private var tokenizer: StringTokenizer? = null

    fun nextString(): String {
        return reader.readLine()
    }

    fun nextInt(): Int {
        return readNextToken().toInt()
    }

    fun nextLong(): Long {
        return readNextToken().toLong()
    }

    fun readArrayOfInt(): IntArray {
        return readArray { it.toInt() }
    }

    fun readArrayOfLong(): LongArray {
        return readArray { it.toLong() }
    }

    private fun readNextToken(): String {
        while (tokenizer == null || !tokenizer!!.hasMoreTokens()) {
            val line = reader.readLine() ?: exitProcess(0)
            tokenizer = StringTokenizer(line)
        }
        return tokenizer!!.nextToken()
    }

    private fun <T> readArray(parser: (String) -> T): Array<T> {
        val line = reader.readLine() ?: return arrayOf()
        val parts = line.trim().split(Regex("\\s+"))
        @Suppress("UNCHECKED_CAST")
        return parts.map(parser).toTypedArray() as Array<T>
    }

    override fun close() {
        reader.close()
    }
}

